def checked_derivative(raw,expected,edits):
 assert hashlib.sha256(raw).hexdigest()==expected,'exact held source'
 text=raw.decode()
 for old,new,count in edits:
  assert text.count(old)==count,('exact seam',old,count)
  text=text.replace(old,new)
 inverse=text
 for old,new,count in reversed(edits):
  assert inverse.count(new)==count,('exact inverse seam',new,count)
  inverse=inverse.replace(new,old)
 assert inverse.encode()==raw,'byte-exact original inverse'
 return text
def derive_fault_context(text):return checked_derivative(text.encode(),_CONTEXT_BASE_SHA,_CONTEXT_EDITS)
